mapper.select:
SELECT  FROM t_channel_statement_line WHERE statement_id = #{statementId} AND line_no IN
#{lineNo}
ORDER BY line_no

SELECT  FROM t_channel_statement_line
WHERE clearing_account_id = #{clearingAccountId} AND reference_type = #{referenceType} AND external_transaction_id = #{externalTransactionId}
ORDER BY id

SELECT  FROM t_channel_statement_line
WHERE clearing_account_id = #{clearingAccountId} AND match_status = 'UNMATCHED' AND create_time < #{createdBefore}
ORDER BY create_time, id LIMIT #{limit}

SELECT  FROM t_channel_statement_line l
JOIN t_channel_statement s ON s.id = l.statement_id AND s.status = 'MATCHING'
WHERE l.clearing_account_id = #{clearingAccountId} AND l.match_status = 'UNMATCHED'
  AND l.line_type IN ('PAYMENT', 'REFUND', 'CHARGEBACK') AND l.create_time < #{createdBefore}
ORDER BY l.create_time, l.id LIMIT #{limit}

SELECT  FROM t_channel_statement_line l
JOIN t_channel_statement s ON s.id = l.statement_id

ORDER BY l.transaction_date DESC, l.id DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE t_channel_statement_line
SET platform_txn_id = #{platformTxnId}, match_method = #{matchMethod}, matched_time = #{matchedTime}, actual_fee = #{actualFee}, resolution_id = #{resolutionId}, match_status = #{matchStatus}, version = version + 1, update_time = #{now}
WHERE id = #{record.id} AND version = #{record.version}

UPDATE t_channel_statement_line l
JOIN (VALUES
ROW(#{c.record.id}, #{c.record.version}, #{c.platformTxnId}, #{c.matchMethod}, #{c.matchedTime}, #{c.actualFee}, #{c.resolutionId}, #{c.matchStatus})
) AS v (id, version, platform_txn_id, match_method, matched_time, actual_fee, resolution_id, match_status)
  ON l.id = v.id AND l.version = v.version
SET l.platform_txn_id = v.platform_txn_id, l.match_method = v.match_method, l.matched_time = v.matched_time, l.actual_fee = v.actual_fee, l.resolution_id = v.resolution_id, l.match_status = v.match_status, l.version = l.version + 1, l.update_time = #{now}
WHERE l.id IN #{c.record.id}
